/** `[code, name]` for a code (`"ar"`, `"ar-EG"`) or a name. The code is null for a name this table does not know. */
export function describeLanguage(language: string, name?: string): [string | null, string] {
    const value = language.trim();
    const key = value.toLowerCase().replace(/_/g, "-");
    const base = key.split("-")[0] ?? key;
    const known = LANGUAGE_NAMES[key];
    if (known) return [base, name ?? known];
    const baseName = LANGUAGE_NAMES[base];
    if (key.includes("-") && baseName) return [base, name ?? baseName];
    for (const [code, label] of Object.entries(LANGUAGE_NAMES)) {
        if (label.toLowerCase() === key) return [code.split("-")[0] ?? code, name ?? label];
    }
    return [null, name ?? value];
}
